      "module_name": "Mathlib.LinearAlgebra.DFinsupp",
      "kind": "definition",
      "type": "{ι : Type u_1} →\n  {R : Type u_3} →\n    {M : ι → Type u_5} →\n      {N : Type u_6} →\n        [inst : Semiring R] →\n          [inst_1 : (i : ι) → AddCommMonoid (M i)] →\n            [inst_2 : (i : ι) → Module R (M i)] →\n              [inst_3 : AddCommMonoid N] →\n                [inst_4 : Module R N] → [DecidableEq ι] → ((i : ι) → M i →ₗ[R] N) → (Π₀ (i : ι), M i) →ₗ[R] N"
    },
    {
