      "type": "{α : Type u_1} →\n  {M : Type u_2} →\n    {N : Type u_3} →\n      {R : Type u_5} →\n        {R₂ : Type u_6} →\n          (S : Type u_8) →\n            [inst : Semiring R] →\n              [inst_1 : Semiring R₂] →\n                [inst_2 : Semiring S] →\n                  [inst_3 : AddCommMonoid M] →\n                    [inst_4 : Module R M] →\n                      [inst_5 : AddCommMonoid N] →\n                        [inst_6 : Module R₂ N] →\n                          {σ : R →+* R₂} →\n                 ..."
    },
    {
      "name": "LinearMap.finsupp_sum_apply",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LSum",
      "kind": "theorem",
      "type": "∀ {R : Type u_4} {R₂ : Type u_5} {M : Type u_6} {M₂ : Type u_7} {ι : Type u_8} [inst : Semiring R]\n  [inst_1 : Semiring R₂] [inst_2 : AddCommMonoid M] [inst_3 : AddCommMonoid M₂] {σ₁₂ : R →+* R₂} [inst_4 : Module R M]\n  [inst_5 : Module R₂ M₂] {γ : Type u_9} [inst_6 : Zero γ] (t : ι →₀ γ) (g : ι → γ → M →ₛₗ[σ₁₂] M₂) (b : M),\n  (t.sum g) b = t.sum fun i d => (g i d) b"
    },
    {
      "name": "Finsupp.lsum_single",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LSum",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_5} {R₂ : Type u_6} (S : Type u_8) [inst : Semiring R]\n  [inst_1 : Semiring R₂] [inst_2 : Semiring S] [inst_3 : AddCommMonoid M] [inst_4 : Module R M]\n  [inst_5 : AddCommMonoid N] [inst_6 : Module R₂ N] {σ : R →+* R₂} [inst_7 : Module S N] [inst_8 : SMulCommClass R₂ S N]\n  (f : α → M →ₛₗ[σ] N) (i : α) (m : M), ((Finsupp.lsum S) f) (Finsupp.single i m) = (f i) m"
    },
    {
      "name": "LinearMap.dfinsuppSum_apply",
      "module_name": "Mathlib.LinearAlgebra.DFinsupp",
      "kind": "theorem",
      "type": "∀ {R : Type u_7} {R₂ : Type u_8} {M : Type u_9} {M₂ : Type u_10} {ι : Type u_11} [inst : Semiring R]\n  [inst_1 : Semiring R₂] [inst_2 : AddCommMonoid M] [inst_3 : AddCommMonoid M₂] {σ₁₂ : R →+* R₂} [inst_4 : Module R M]\n  [inst_5 : Module R₂ M₂] {γ : ι → Type u_12} [inst_6 : DecidableEq ι] [inst_7 : (i : ι) → Zero (γ i)]\n  [inst_8 : (i : ι) → (x : γ i) → Decidable (x ≠ 0)] (t : Π₀ (i : ι), γ i) (g : (i : ι) → γ i → M →ₛₗ[σ₁₂] M₂) (b : M),\n  (t.sum g) b = t.sum fun i d => (g i d) b"
    },
    {
      "name": "LinearMap.coe_finsupp_sum",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LSum",
      "kind": "theorem",
      "type": "∀ {R : Type u_4} {R₂ : Type u_5} {M : Type u_6} {M₂ : Type u_7} {ι : Type u_8} [inst : Semiring R]\n  [inst_1 : Semiring R₂] [inst_2 : AddCommMonoid M] [inst_3 : AddCommMonoid M₂] {σ₁₂ : R →+* R₂} [inst_4 : Module R M]\n  [inst_5 : Module R₂ M₂] {γ : Type u_9} [inst_6 : Zero γ] (t : ι →₀ γ) (g : ι → γ → M →ₛₗ[σ₁₂] M₂),\n  ⇑(t.sum g) = ⇑(t.sum fun i d => g i d)"
    }
